package jakarta.persistence;
public interface EntityManager extends AutoCloseable { void persist(Object e); <T> T merge(T e); void remove(Object e); <T> T find(Class<T> c, Object pk); <T> T getReference(Class<T> c, Object pk); void flush(); void refresh(Object e); default void clear() { } default void detach(Object e) { } default boolean contains(Object e) { return false; } default boolean isOpen() { return true; } default void setProperty(String name, Object value) { } default java.util.Map<String, Object> getProperties() { return java.util.Map.of(); } <T> TypedQuery<T> createQuery(String q, Class<T> c); Query createNativeQuery(String sql); EntityTransaction getTransaction(); void close(); <T> T unwrap(Class<T> cls); }
